// filterProducer turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterProducer(f *api.ProducerFilter) (predicate.Producer, error) {
	ps := make([]predicate.Producer, 0, 1)
	if f.HasRef() {
		p, err := bare.ProducerPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasTenant() {
		w := f.GetTenant()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "tenant: %s", err)
			}

			ps = append(ps, producer.TenantIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.TenantPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, producer.HasTenantWith(q))
		}
	}
	if f.HasSet() {
		w := f.GetSet()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "set: %s", err)
			}

			ps = append(ps, producer.SetIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.SetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, producer.HasSetWith(q))
		}
	}
	if f.HasSite() {
		w := f.GetSite()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "site: %s", err)
			}

			ps = append(ps, producer.SiteIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.SitePick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, producer.HasSiteWith(q))
		}
	}
	if m := f.GetLabels(); len(m) > 0 {
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)

		for _, k := range ks {
			ps = append(ps, predicate.Producer(func(s *sql.Selector) {
				s.Where(sql.And(
					sqljson.HasKey(producer.FieldLabels, sqljson.Path(k)),
					sqljson.ValueEQ(producer.FieldLabels, m[k], sqljson.Path(k)),
				))
			}))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return producer.And(ps...), nil
}

// ProducerService is the prefix of every Rpc of that service, which is how a
// change is known to be about a Producer. A service is named for the entity it
// is about, so the name carries it.
var ProducerService = watch.ServiceOf(api.ProducerService_Get_FullMethodName)

// Watch answers with the Producers this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkProducer) Watch(req *api.ProducerWatchRequest, out grpc.ServerStreamingServer[api.ProducerWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > ProducerFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), ProducerFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchProducerKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, ProducerService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*api.ProducerWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, api.ProducerWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(api.ProducerWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkProducer) watchNow(
	ctx context.Context, req *api.ProducerWatchRequest, out grpc.ServerStreamingServer[api.ProducerWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, api.ProducerListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*api.ProducerWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, api.ProducerWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(api.ProducerWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

// watchRead answers with the row as it is now, or nil when it is no longer
// one this caller may see -- erased, walled off, or no longer matching what
// they asked for. The three are deliberately indistinguishable to a caller:
// a stream that told them apart would be saying which rows stopped being
// theirs, which is the thing the wall is for.
//
// The Get is what keeps the wall out of this file. It goes through the same
// server every other read does, with the context of the caller who asked, so
// a row they may not see comes back NotFound and is never sent.
func (s sinkProducer) watchRead(
	ctx context.Context, watching []pdid.Id, k pdid.Id,
) (*api.Producer, error) {
	// Not one of the rows this stream is about. Asked before the read, so a
	// busy table costs a stream nothing for the rows it does not watch.
	if !slices.Contains(watching, k) {
		return nil, nil
	}

	v, err := s.Get(ctx, api.ProducerGetRequest_builder{
		Ref: api.ProducerRef_builder{Id: k.Bytes()}.Build(),
	}.Build())
	if err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, nil
		}

		return nil, err
	}

	return v, nil
}

// watchProducerKeys is the rows a stream is about, resolved once when it opens.
//
// A filter names a row and a row is named several ways -- by identifier, or
// by whatever unique index the schema declared. Resolving them here rather
// than comparing them per event does three things: the comparison afterwards
// is an identifier against an identifier, a name that names nothing is
// refused when the stream opens rather than silently watching nothing, and a
// row renamed while the stream is open goes on being the row that was asked
// for -- which is what somebody watching a thing meant.
func (s sinkProducer) watchProducerKeys(
	ctx context.Context, fs []*api.ProducerFilter,
) ([]pdid.Id, error) {
	ks := make([]pdid.Id, 0, len(fs))
	for i, f := range fs {
		if !f.HasRef() {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters[%d]: a watch says which rows it is about by naming them", i)
		}

		v, err := s.Get(ctx, api.ProducerGetRequest_builder{Ref: f.GetRef()}.Build())
		if err != nil {
			return nil, err
		}

		k, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		ks = append(ks, k)
	}

	return ks, nil
}

type sinkReader struct {
	api.ReaderServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Reader() api.ReaderServiceServer {
	return sinkReader{s.Server.Reader(), s.Server.Store, s.w, s.namer, s.joined}
}

// Add decides the name, and refuses one that was given and cannot be one.
//
// It goes through [Sink.WithNamer], which is unset in most deployments and
// then means: fold what was given, and make a name up when nothing was --
// for the reason `bare.Minter` makes a key up. An app whose rows have to
// be named says so with `slug.Required`; see `slug.Names` for why that is
// the way round it is.
//
// The request is copied rather than written to. It belongs to whoever
// called, and for a call made in this process that is a message they may
// still be holding -- a server that folded a caller's own field would be
// changing a value they can read back.
func (s sinkReader) Add(ctx context.Context, req *api.ReaderAddRequest) (*api.Reader, error) {
	// How many names to try. More than one only when the caller named
	// nothing -- then the name is this server's and a collision is this
	// server's to resolve. A name the caller gave is theirs, and quietly
	// choosing a different one would write a row they did not ask for.
	//
	// And only when this Add opens its own transaction; see [Sink.joined].
	tries := 1
	if req.GetAlias() == "" && !s.joined {
		tries = slug.Tries
	}

	for try := 0; ; try++ {
		v, err := slug.NameWith(ctx, s.namer, "shale.Reader", req.GetAlias(), req)
		if err != nil {
			return nil, pderr.At("alias", err)
		}

		// The request is copied rather than written to, and copied again on
		// each try: it belongs to whoever called, and for a call made in this
		// process that is a message they may still be holding.
		r := proto.CloneOf(req)
		r.SetAlias(v)

		res, err := s.ReaderServiceServer.Add(ctx, r)
		if err == nil || try+1 >= tries || status.Code(err) != codes.AlreadyExists {
			// Whatever it was, said in the words it was said in. Rewriting
			// it into "no free name" would assert the one thing this cannot
			// know -- a duplicate key is the same code -- and would say it
			// loudest exactly when it is wrong.
			return res, err
		}
	}
}

// Patch folds a name it was given, and says nothing about one it was not.
//
// The presence is the whole of the difference from [sinkReader.Add]: a patch
// that does not mention the alias is not a patch setting it to the empty
// string, and refusing one would make every patch of any other field carry
// the name along.
//
// The namer is **not** asked here, and that is the second difference. It
// decides the name of a row being made; a patch that cleared the alias is
// a caller asking for something invalid, and answering that with an
// invented name would hand them a row they did not ask for.
func (s sinkReader) Patch(ctx context.Context, req *api.ReaderPatchRequest) (*api.Reader, error) {
	if !req.HasAlias() {
		return s.ReaderServiceServer.Patch(ctx, req)
	}

	v, err := slug.ParseAlias(req.GetAlias())
	if err != nil {
		return nil, pderr.At("alias", err)
	}

	req = proto.CloneOf(req)
	req.SetAlias(v)

	return s.ReaderServiceServer.Patch(ctx, req)
}

// orderReader is how Readers come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderReader = []sqlpage.Order{
	{Column: reader.FieldDateCreated, Desc: false},
	{Column: reader.FieldId, Desc: false},
}

const (
	// ReaderPageSize is what a request that did not say gets, and
	// ReaderPageLimit is the most it gets however loudly it asks.
	ReaderPageSize  = 20
	ReaderPageLimit = 100

	// ReaderFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	ReaderFilterLimit = 32
)

// List answers with the Readers that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkReader) List(ctx context.Context, req *api.ReaderListRequest) (*api.ReaderListResponse, error) {
	q := s.store.Db.Reader.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.ReaderNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > ReaderFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), ReaderFilterLimit)
		}

		ps := make([]predicate.Reader, 0, len(fs))
		for i, f := range fs {
			p, err := filterReader(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(reader.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderReader, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), ReaderPageSize, ReaderPageLimit)
	us, err := q.Order(reader.ByDateCreated(), reader.ById()).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*api.Reader, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := api.ReaderListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterReader turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterReader(f *api.ReaderFilter) (predicate.Reader, error) {
	ps := make([]predicate.Reader, 0, 1)
	if f.HasRef() {
		p, err := bare.ReaderPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasTenant() {
		w := f.GetTenant()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "tenant: %s", err)
			}

			ps = append(ps, reader.TenantIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.TenantPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, reader.HasTenantWith(q))
		}
	}
	if m := f.GetLabels(); len(m) > 0 {
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)

		for _, k := range ks {
			ps = append(ps, predicate.Reader(func(s *sql.Selector) {
				s.Where(sql.And(
					sqljson.HasKey(reader.FieldLabels, sqljson.Path(k)),
					sqljson.ValueEQ(reader.FieldLabels, m[k], sqljson.Path(k)),
				))
			}))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return reader.And(ps...), nil
}

// ReaderService is the prefix of every Rpc of that service, which is how a
// change is known to be about a Reader. A service is named for the entity it
// is about, so the name carries it.
var ReaderService = watch.ServiceOf(api.ReaderService_Get_FullMethodName)

// Watch answers with the Readers this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkReader) Watch(req *api.ReaderWatchRequest, out grpc.ServerStreamingServer[api.ReaderWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > ReaderFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), ReaderFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchReaderKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, ReaderService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*api.ReaderWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, api.ReaderWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(api.ReaderWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkReader) watchNow(
	ctx context.Context, req *api.ReaderWatchRequest, out grpc.ServerStreamingServer[api.ReaderWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, api.ReaderListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*api.ReaderWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, api.ReaderWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(api.ReaderWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

