// filterSet turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterSet(f *api.SetFilter) (predicate.Set, error) {
	ps := make([]predicate.Set, 0, 1)
	if f.HasRef() {
		p, err := bare.SetPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasTenant() {
		w := f.GetTenant()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "tenant: %s", err)
			}

			ps = append(ps, set.TenantIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.TenantPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, set.HasTenantWith(q))
		}
	}
	if f.HasSite() {
		w := f.GetSite()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "site: %s", err)
			}

			ps = append(ps, set.SiteIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.SitePick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, set.HasSiteWith(q))
		}
	}
	if m := f.GetLabels(); len(m) > 0 {
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)

		for _, k := range ks {
			ps = append(ps, predicate.Set(func(s *sql.Selector) {
				s.Where(sql.And(
					sqljson.HasKey(set.FieldLabels, sqljson.Path(k)),
					sqljson.ValueEQ(set.FieldLabels, m[k], sqljson.Path(k)),
				))
			}))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return set.And(ps...), nil
}

