// orderSigningKey is how SigningKeys come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderSigningKey = []sqlpage.Order{
	{Column: signingkey.FieldDateCreated, Desc: false},
	{Column: signingkey.FieldId, Desc: false},
}

const (
	// SigningKeyPageSize is what a request that did not say gets, and
	// SigningKeyPageLimit is the most it gets however loudly it asks.
	SigningKeyPageSize  = 20
	SigningKeyPageLimit = 100

	// SigningKeyFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	SigningKeyFilterLimit = 32
)

// List answers with the SigningKeys that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkSigningKey) List(ctx context.Context, req *api.SigningKeyListRequest) (*api.SigningKeyListResponse, error) {
	q := s.store.Db.SigningKey.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.SigningKeyNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > SigningKeyFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), SigningKeyFilterLimit)
		}

		ps := make([]predicate.SigningKey, 0, len(fs))
		for i, f := range fs {
			p, err := filterSigningKey(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(signingkey.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderSigningKey, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), SigningKeyPageSize, SigningKeyPageLimit)
	us, err := q.Order(signingkey.ByDateCreated(), signingkey.ById()).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*api.SigningKey, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := api.SigningKeyListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterSigningKey turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterSigningKey(f *api.SigningKeyFilter) (predicate.SigningKey, error) {
	ps := make([]predicate.SigningKey, 0, 1)
	if f.HasRef() {
		p, err := bare.SigningKeyPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return signingkey.And(ps...), nil
}

// SigningKeyService is the prefix of every Rpc of that service, which is how a
// change is known to be about a SigningKey. A service is named for the entity it
// is about, so the name carries it.
var SigningKeyService = watch.ServiceOf(api.SigningKeyService_Get_FullMethodName)

// Watch answers with the SigningKeys this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkSigningKey) Watch(req *api.SigningKeyWatchRequest, out grpc.ServerStreamingServer[api.SigningKeyWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > SigningKeyFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), SigningKeyFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchSigningKeyKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, SigningKeyService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*api.SigningKeyWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, api.SigningKeyWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(api.SigningKeyWatchResponse_builder{Items: items}.Build())
		})
}

